def _as_list(v):
    return v if isinstance(v, list) else [v]

def find_wildcards(policy):
    out = []
    for s in policy["Statement"]:
        if s["Effect"] != "Allow":
            continue
        broad_action = any(a == "*" or a.endswith(":*") for a in _as_list(s["Action"]))
        broad_resource = "*" in _as_list(s["Resource"])
        if broad_action or broad_resource:
            out.append(s["Sid"])
    return sorted(out)

