from fnmatch import fnmatchcase

def _decide(statements, action):
    result = None
    for s in statements:
        acts = s["Action"] if isinstance(s["Action"], list) else [s["Action"]]
        if any(fnmatchcase(action.lower(), p.lower()) for p in acts):
            if s["Effect"] == "Deny":
                return "deny"
            result = "allow"
    return result

def effective(identity, boundary, scp, action):
    layers = [identity, scp] + ([boundary] if boundary is not None else [])
    results = [_decide(layer, action) for layer in layers]
    if "deny" in results:
        return False
    return all(r == "allow" for r in results)
